const GUIDE_TITLE = {
  "live": "人生指南",
  "cook": "做饭指南",
  "skill": "技能指南"
}
const GUIDE_REPO = {
  "live": "eternity4719/HowToLiveBetter",
  "cook": "Anduin2017/HowToCook",
  "skill": "PKUFlyingPig/cs-self-learning"
}

function guideCards(id) { return CARDS.filter((c) => c.guide === id) }
function allCards() { return CARDS.slice() }
function totalCards() { return CARDS.length }
function cardCountOf(id) { return guideCards(id).length }
function guideTitleOf(id) { return GUIDE_TITLE[id] || '' }
function guideRepoOf(id) { return GUIDE_REPO[id] || '' }
function cardAt(id, index) {
  const list = guideCards(id)
  const i = Math.max(0, Math.min(list.length - 1, Number(index) || 0))
  return list[i] || null
}
function indexOfCard(guide, no) {
  const list = guideCards(guide)
  const i = list.findIndex((c) => c.no === String(no))
  return i < 0 ? 0 : i
}
function chaptersOf(id) {
  const out = []
  const map = {}
  guideCards(id).forEach((c) => {
    if (!map[c.chapter]) { map[c.chapter] = { name: c.chapter, items: [] }; out.push(map[c.chapter]) }
    map[c.chapter].items.push({ no: c.no, title: c.title })
  })
  return out
}
function searchCards(query, limit) {
  const kw = String(query || '').trim().toLowerCase()
  if (!kw) return []
  const max = Number(limit) || 60
  const out = []
  for (let i = 0; i < CARDS.length && out.length < max; i++) {
    const c = CARDS[i]
    const text = (c.chapter + ' ' + c.label + ' ' + c.title + ' ' + c.points.join(' ') + ' ' + c.action + ' ' + c.keywords + ' ' + c.guideTitle).toLowerCase()
    if (text.indexOf(kw) < 0) continue
    const hit = c.points.find((p) => p.toLowerCase().indexOf(kw) >= 0)
      || (() => {
        const i = c.keywords.toLowerCase().indexOf(kw)
        if (i < 0) return ''
        return '…' + c.keywords.slice(Math.max(0, i - 6), i + 26) + '…'
      })()
      || (c.title.toLowerCase().indexOf(kw) >= 0 ? c.title : c.chapter)
    out.push({
      guide: c.guide, guideTitle: c.guideTitle, no: c.no, chapter: c.chapter,
      title: c.title, snippet: hit.length > 42 ? hit.slice(0, 42) + '…' : hit,
    })
  }
  return out
}
function hashSeed(str) {
  let h = 2166136261
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619) }
  return h >>> 0
}
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
// 按日期做确定性随机：同一天推荐不变，跨天自动换一批。
function dailyPicks(dateKey, count) {
  const n = Number(count) || 6
  const rnd = mulberry32(hashSeed('life-quest-picks-' + String(dateKey || '')))
  const guides = Object.keys(GUIDE_TITLE)
  const pools = {}
  guides.forEach((g) => { pools[g] = CARDS.filter((c) => c.guide === g) })
  const picked = []
  // 分层随机：三份指南轮流各出 1 张，直到凑满，避免推荐被卡片最多的一份刷屏
  let round = 0
  while (picked.length < n && round < n * 12) {
    const g = guides[round % guides.length]
    const list = pools[g]
    const c = list[Math.floor(rnd() * list.length)]
    if (c && !picked.some((p) => p.guide === c.guide && p.no === c.no)) picked.push(c)
    round++
  }
  return picked.slice(0, n)
}

module.exports = {
  CARDS, GUIDE_TITLE, GUIDE_REPO,
  guideCards, allCards, totalCards, cardCountOf, guideTitleOf, guideRepoOf,
  cardAt, indexOfCard, chaptersOf, searchCards, dailyPicks,
}
